// Geography app (MODE 4 → Apps): a world map with the 177 countries of Natural
// Earth 1:110m, their capitals, a country card, an A–Z list with a letter
// picker, a continent filter and a capitals quiz.
//
// Two layers:
//  * Data (geo_data.cpp, generated by tools/geo/make_geo_data.py): countries,
//    outline rings and points as int16 degrees x100. Read it through
//    countryCount() / country() / ring() / point().
//  * GeoApp: the state machine and the 125x61 mono render. The colour UI
//    (v15, 320x170) reads screen(), selected(), focusBox(), viewport() and the
//    list / search / quiz accessors and draws its own version.
//
// Plain C++17, no allocation after construction except small std::string
// temporaries while rendering; no dependencies beyond the core's Framebuffer,
// font and the DKey enum.
#pragma once
#include <cstddef>
#include <cstdint>
#include <string>
#include <vector>

#include "keys.h"  // calc::DKey
#include "framebuffer.h"

namespace calc {
namespace geo {

// ---------------------------------------------------------------- data ----

// Natural Earth's CONTINENT field. Antarctica and "Seven seas" (the French
// Southern and Antarctic Lands) only show under "All" in the filter.
enum class Continent : uint8_t {
  Africa, Asia, Europe, NorthAmerica, SouthAmerica, Oceania, Antarctica, SevenSeas, Count
};
const char* continentName(Continent c);  // "Africa", "North America", "Seven seas"

struct Point { int16_t lon, lat; };          // degrees x100 (Paris: {233, 4887})
struct Ring { uint16_t first, count; };      // points [first, first+count), closed implicitly

struct Country {
  const char* name;       // Natural Earth NAME, English, UTF-8 ("Côte d'Ivoire", "Dem. Rep. Congo")
  const char* iso3;       // ISO 3166-1 alpha-3; Natural Earth's ADM0_A3 when isoOfficial is false
  const char* capital;    // UTF-8; "" when Natural Earth gives none (Antarctica, Fr. S. Antarctic Lands, N. Cyprus)
  int16_t capLon, capLat;      // capital position, degrees x100 (0,0 when no capital)
  int16_t labelLon, labelLat;  // Natural Earth label point: inside the country; the "centre" for ▲▼
  int16_t box[4];              // zoom box: lonMin, latMin, lonMax, latMax x100 (main part, without far islands)
  uint16_t firstRing;
  uint8_t ringCount;           // ring 0 is the largest (main) ring; holes are rings too (even-odd)
  Continent continent;
  bool isoOfficial;            // false for N. Cyprus (CYN), Somaliland (SOL), Kosovo (KOS)
};

int countryCount();                 // 177; index order = alphabetical by name (accents folded)
const Country& country(int i);
int ringCount();
const Ring& ring(int i);            // global ring index (Country::firstRing + k)
int pointCount();
const Point& point(int i);          // global point index (Ring::first + k)
bool hasCapital(int i);
int findIso(const char* iso3);      // -1 when not found
int findName(const char* name);     // exact NAME match, -1 when not found
// Even-odd test over all of the country's rings (lon/lat in degrees).
bool containsPoint(int i, float lon, float lat);
// Bytes the tables take in flash on a 32-bit target (points, rings, country rows, strings).
size_t dataBytes();

// Geographic window in degrees (lonMin, latMin, lonMax, latMax).
struct GeoBox { float lon0, lat0, lon1, lat1; };

// How the mono map maps lon/lat to pixels: x = cx + (lon - lon) * pxPerDegLon,
// y = cy - (lat - lat) * pxPerDegLat. Equirectangular; when zoomed in, the
// longitude scale is shrunk by cos(latitude) so shapes keep their proportions.
struct Viewport {
  float lon, lat;         // centre of the view
  float pxPerDegLon, pxPerDegLat;
  int x, y, w, h;         // the map rectangle on the 125x61 screen
};

// ------------------------------------------------------------------ app ----

class GeoApp {
 public:
  enum class Screen : uint8_t { Map, Card, List, Search, Quiz };
  // Continent filter (key 4): All, then Africa ... Oceania.
  static constexpr int kFilterCount = 7;
  static constexpr int kZoomLevels = 3;   // 0 world (or the filter's continent), 1 continent, 2 country
  static constexpr int kListRows = 5;     // rows visible in the list (row 1 is its header)

  GeoApp();

  // Back to the map, world view, France selected, no filter, quiz score 0.
  // Keeps the RNG state (seed it with setSeed()).
  void reset();
  // Returns true when the key did something. Keys:
  //  Map:    ◀ ▶ previous/next country (west → east within a continent),
  //          ▲ ▼ nearest country to the north/south, 1 zoom in, 0 zoom out,
  //          = card, 2 list, 3 letter picker, 4 continent filter, 5 quiz, AC leave.
  //  Card:   ◀ ▶ previous/next country, ▲ ▼ scroll, = or AC back to the map.
  //  List:   ▲ ▼ move, ◀ ▶ page, = select (to the map), 3 letter picker, AC map.
  //  Search: arrows move over the letter grid, = add the letter (or OK: open the
  //          list at the first match), DEL erase, AC back to where it was opened.
  //  Quiz:   1-4 answer, then any key for the next question; AC map.
  bool onKey(DKey k, bool shift = false, bool alpha = false);
  // Draws into text rows 1-6 (y >= 8); row 0 is the device's status bar and is
  // left alone. Sets the fb's Up/Down icons when a screen can scroll.
  void render(Framebuffer& fb) const;
  bool wantsExit() const { return exit_; }
  // Clears wantsExit() so the host can open the app again where it was left.
  void resume() { exit_ = false; }

  Screen screen() const { return screen_; }
  int selected() const { return sel_; }
  void select(int country);            // also used by tests and the colour UI
  int zoom() const { return zoom_; }
  int filter() const { return filter_; }           // 0 = All, 1..6 = Africa..Oceania
  static const char* filterName(int f);            // "All", "Africa", ...
  bool inFilter(int country) const;

  // Map geometry. focusBox() is what must be visible (the world, the
  // continent or the selected country's zoom box); viewport() is how the mono
  // render fits it into its 125x45 map area. The colour UI can fit focusBox()
  // into its own rectangle instead.
  GeoBox focusBox() const;
  Viewport viewport() const;
  // Projects through viewport(); returns false when outside the map rectangle.
  bool project(float lon, float lat, int& x, int& y) const;

  // Spatial navigation (also what ◀ ▶ ▲ ▼ do on the map).
  int nextCountry(int from, int dir) const;    // dir +1 east / -1 west, wraps, stays in the filter
  int northSouth(int from, int dir) const;     // dir +1 north / -1 south; `from` when none
  const std::vector<int>& order() const { return order_; }   // the ◀ ▶ cycle (all countries)

  // Card
  int cardScroll() const { return cardScroll_; }
  std::vector<std::string> cardLines() const;   // the card's text, wrapped to 25 columns

  // List: countries in the filter, alphabetical; cursor and first visible row.
  const std::vector<int>& listItems() const { return list_; }
  int listCursor() const { return listCur_; }
  int listTop() const { return listTop_; }

  // Search: typed prefix, grid cursor (0..26; 26 = OK), first match or -1.
  const std::string& searchPrefix() const { return prefix_; }
  int searchCursor() const { return gridCur_; }
  int searchMatch() const;
  int searchMatches() const;
  static constexpr int kGridCells = 27;        // A..Z then OK
  static constexpr int kGridCols = 9;

  // Quiz
  enum class QuizKind : uint8_t { CapitalOf, CountryOf };
  struct Quiz {
    QuizKind kind = QuizKind::CapitalOf;
    int subject = 0;           // the country asked about
    int choices[4] = {0, 0, 0, 0};  // country indices; answers are their capitals (CapitalOf) or names
    int correct = 0;           // 0-3
    int picked = -1;           // 0-3 once answered, else -1
    int score = 0, asked = 0;  // right answers / questions answered
  };
  const Quiz& quiz() const { return quiz_; }
  void setSeed(uint32_t seed);   // the host's randomness (e.g. esp_random(), or a fixed seed in tests)
  void newQuestion();

 private:
  bool keyMap(DKey k);
  bool keyCard(DKey k);
  bool keyList(DKey k);
  bool keySearch(DKey k);
  bool keyQuiz(DKey k);
  void openList(int cursorCountry);
  void rebuildList();
  void setFilter(int f);
  uint32_t rand();

  void drawMap(Framebuffer& fb) const;
  void drawCard(Framebuffer& fb) const;
  void drawList(Framebuffer& fb) const;
  void drawSearch(Framebuffer& fb) const;
  void drawQuiz(Framebuffer& fb) const;

  Screen screen_ = Screen::Map;
  bool exit_ = false;
  int sel_ = 0;
  int zoom_ = 0;
  int filter_ = 0;
  int cardScroll_ = 0;
  std::vector<int> order_;   // ◀ ▶ order: continent, then west → east
  std::vector<int> pos_;     // country -> index in order_
  std::vector<int> list_;
  int listCur_ = 0, listTop_ = 0;
  std::string prefix_;
  int gridCur_ = 0;
  Screen searchFrom_ = Screen::Map;   // where AC in the letter picker goes back to
  Quiz quiz_;
  uint32_t rng_ = 0x9E3779B9u;
};

// Accent folding for the mono font (it has no accented letters): "Brasília" → "Brasilia".
std::string asciiFold(const std::string& utf8);

}  // namespace geo
}  // namespace calc
